def cached(cache, key=hashkey, lock=None):
	"""
	Returns a decorator function that saves the results in the cache
	"""
	def wrapper(f):
		@wraps(f)
		def wrapped(*args, **kwargs):
			if not hasattr(f, '_cache'):
				f._cache = {}
			if not hasattr(f, '_cache_key'):
				f._cache_key = hash(key(args))
			if f._cache_key in f._cache:
				return f._cache[f._cache_key]
			result = f(*args, **kwargs)
			f._cache[f._cache_key] = result
			if lock is None:
				lock = Lock()
			with lock:
				f._cache[f._cache_key] = result
			return result
		return wrapped
	return wrapper

def mru_cache(maxsize=128, typed=False):
	"""
	Decorator to wrap a function with a memoizing callable that saves
up to `maxsize` results based on a Most Recently Used (MRU)
algorithm.
	"""
	def wrapper(func):
		"""Wrapper for decorating functions."""
		# pylint: disable=missing-docstring
		@wraps(func)
		def wrapped(*args, **kwargs):
			"""Wrapper for decorating functions."""
			if not hasattr(wrapped, '_cache'):
				wrapped._cache = {}
			if func.__name__ in wrapped._cache:
				del wrapped._cache[func.__name__]
			wrapped._cache[func.__name__] = func(*args, **kwargs)
			return wrapped._cache[func.__name__]
		return wrapped

	# pylint: disable=unused-argument
	# pylint: disable=missing-docstring
	return wrapper

def lru_cache(maxsize=128, typed=False):
	"""
	Decorator to wrap a function with a memoizing callable that saves
up to `maxsize` results based on a Least Recently Used (LRU)
algorithm.
	"""
	def decorator(f):
		"""The actual decorator."""
		# pylint: disable=missing-docstring

		@wraps(f)
		def wrapper(*args, **kwargs):
			"""The wrapped function."""
			# pylint: disable=missing-docstring
			if not hasattr(wrapper, '_memoized_results'):
				wrapper._memoized_results = {}
				wrapper._memoized_keys = set()
			else:
				wrapper._memoized_keys = wrapper._memoized_keys.union(kwargs.keys())
			key = _get_key(args, kwargs)

			if key in wrapper._memoized_results:
				return wrapper._memoized_results[key]
			result = f(*args, **kwargs)
			wrapper._memoized_results[key] = result
			wrapper._memoized_keys.difference_update(key)
			if len(wrapper._memoized_keys) > maxsize:
				del wrapper._memoized_results[wrapper._memoized_keys.pop()]
			return result
		return wrapper
	return decorator

def lfu_cache(maxsize=128, typed=False):
	"""
	Decorator to wrap a function with a memoizing callable that saves
up to `maxsize` results based on a Least Frequently Used (LFU)
algorithm.
	"""
	def wrapper(f):
		"""Wrapper for decorating functions."""
		# pylint: disable=missing-docstring
		@wraps(f)
		def wrapped(*args, **kwargs):
			"""Wrapper for decorating functions."""
			if not hasattr(wrapped, '_cache'):
				wrapped._cache = {}
				wrapped._cache_size = 0

			if len(wrapped._cache) > maxsize:
				del wrapped._cache[0]
			wrapped._cache_size += 1
			return f(*args, **kwargs)

		# pylint: enable=missing-docstring
		wrapped._cache = {}
		wrapped._cache_size = 0
		return wrapped
		return wrapper

