def _group_files_by_xml_filename(source, xmls, files):
	"""
	Groups files by xmls and returns data in dict format.
	"""
	grouped = {}
	for xml_file in xmls:
		if xml_file not in grouped:
			grouped[xml_file] = []
		grouped[xml_file].append(files[xml_file])
	return grouped

def match_file_by_prefix(prefix, file_path):
	"""
	Given a filepath, return true if the basename of the filepath is startswith the given prefix plus "-" or the given prefix plus "."
	"""
	if not os.path.exists(file_path):
		return False

	file_basename = os.path.basename(file_path)
	if len(file_basename) == 0:
		return False

	if file_basename.startswith(prefix + "-"):
		return True
	elif file_basename.startswith(prefix + "."):
		return True
	else:
		return False

def _explore_folder(folder):
	"""
	Groups files in the given group by using _group_files_by_xml_filename.
	"""
	for root, dirs, files in os.walk(folder):
		for f in files:
			file_path = os.path.join(root, f)
			if not file_path.endswith('.xml'):
				continue
			file_name = file_path[:-len('.xml')]
			yield (file_name, _group_files_by_xml_filename(file_path))

def _eval_file(prefix, file_path):
	"""
	Identify the type of the given file. Return None if the file do not match the given prefix or the type of the file is xml. Return dict with the key of component_id, file_path if the type of the file is "pdf", return dict with the key of component_id, file_path, ftype, file_path if the type of the file is not "pdf".
	"""
	if os.path.splitext(file_path)[1] == '.xml':
		return {'component_id': 'xml', 'file_path': file_path}
	elif os.path.splitext(file_path)[1] == '.pdf':
		return {'component_id': 'pdf', 'file_path': file_path}

