def size_to_bytes(size: str) -> int:
	"""
	Convert human readable file size to bytes

    Args:
            size: str, a string representing a human readable file size (eg: '500K')
    Returns:
            int: file size in bytes
	"""
	if not size or len(size) == 0:
		return 0
	size = re.sub(r'[^0-9a-zA-Z]+', '', size)
	if size.endswith('K'):
		size *= 1024
	elif size.endswith('M'):
		size *= 1024 * 1024
	elif size.endswith('G'):
		size *= 1024 * 1024 * 1024
	else:
		raise ValueError("Unknown unit in path specification")
	return int(float(size))

def _dictsum(dicts):
	"""
	Sum values with the same key in the dictionaries. And return a new dictionary.
    Example:
        given two dictionaries: dict1: {'a': 1, 'b': 2}, dict2: {'a': 5, 'b': 0}
        return a dictionary: dic:{'a': 6, 'b': 2}
    Returns: dict
	"""
	result = {}
	for k, v in dicts.items():
		result[k] = sum(v.values())
	return result

