def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
	"""
	Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    @param archive_path : archive file path
    @param filename: File name
    @param tmp_path: Temporary file path
    @return Repo URL
	"""
	if os.path.exists(archive_path):
		with open(archive_path, "rb") as f:
			archive = tarfile.open(fileobj=f)
	else:
		raise ValueError("Archive %s does not exist" % archive_path)

	# Get all files in the archive
	files = [f for f in archive.getnames() if f.endswith(".tar")]
	# Unpack the archive into a temporary directory
	tempdir = tempfile.mkdtemp()
	try:
		archive.extractall(path=tempdir)
	except Exception as e:
		raise RuntimeError("Error unpacking archive %s: %s" % (archive_path, e))
	# Create a temporary file to hold the extracted contents of the archive
	file_path = "%s/%s" % (tempdir, filename or "")
	try:
		with open(file_path, "wb") as f:
			for chunk in archive:
				f.write(chunk)
	except Exception as e:
		raise RuntimeError("Error extracting archive %s: %s" % (archive_path, e))

	# Remove the temporary directory
	shutil.rmtree(tempdir)

	return "file://%s" % file_path

def parse_frequency(frequency):
	"""
	Given a frequency string with a number and a unit of time, return a corresponding
     datetime.timedelta instance.
     If the frequency is None or "always", return None.
     Raise ValueError if the given frequency cannot be parsed.
     For instance, given "3 timeunit", return datetime.timedelta(timeunit=3)

     @param frequency :  A frequency string "number timeunit"

    @return str, the corresponding datetime
	"""
	if not frequency:
		return None

	freq = frequency.strip()
	if freq.lower() == 'always':
		return None

	# Parse the frequency
	number, unit = re.findall(r'(\d+)(?:\s*[a-zA-Z]+)?', freq)[0:2]
	number = int(number)
	if unit.lower() in ('days', 'hours'):
		number *= 60 * 60
	elif unit.lower() in ('minutes',):
		number *= 60
	elif unit.lower() in ('seconds',):
		number *= 1
	else:
		raise ValueError('Invalid frequency %r' % (freq,))

	# Parse the unit
	if unit.lower() in ('weeks',):
		number *= 7
	elif unit.lower() in ('months',):
		number *= 30
	elif unit.lower() in ('years',):
		number *= 365
	else:
		raise ValueError('Invalid frequency %r' % (freq,))

	return timedelta(**{unit: number})

def _resolve_string(matcher):
	"""
	Get the value from environment given a matcher containing a name and an optional default value in its group dict.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
	"""
	value = os.environ.get(matcher.group(1))
	if value:
		return value
	elif matcher.group(2) is None:
		raise ValueError("Environment variable %s was not found" % matcher.group(1))
	else:
		return matcher.group(2)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
	"""
	A list of command is given. Run the given command(s) with the given arguments use a subprocess. Return the running result (stdout and returncode)
	"""
	if not isinstance(commands, list):
		commands = [commands]
	if not isinstance(args, list):
		args = [args]

	command_list = []
	for c in commands:
		command_list.append(c)

	return_code = 0
	try:
		subprocess.check_output(command_list, stderr=subprocess.STDOUT, shell=True, universal_newlines=True, cwd=cwd, env=env)
	except Exception as e:
		print("Error: " + str(e))
		return_code = -1

	if hide_stderr:
		return_code = 0 if return_code == 0 else -1

	if verbose:
		print("\n".join(command_list))

	if return_code != 0:
		raise RuntimeError("Command failed with exit code %d" % return_code)

	return return_code

