def parse_diaspora_webfinger(document: str) -> Dict:
	"""
	The webfinger is obtained by reading the document in JSON format, the value of hcard_url in the webfinger is the value of href in links in the document.
	"""
	try:
		data = json.loads(document)
	except ValueError as e:
		raise ValueError("Could not parse JSON from %s" % document)

	if "hcard_url" not in data or "href" not in data["hcard_url"]:
		raise ValueError("Could not find hcard_url")

	return {
		"name": data["name"],
		"url": data["hcard_url"]["href"]
	}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
	"""
	Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
	"""
	try:
		response = requests.get(
			"https://api.github.com/user/links/webfinger/{0}".format(handle),
			headers={"Accept": "application/vnd.github.v3.octocat"}
		)
		if response.status_code == 200:
			return response.text
		else:
			raise Exception("Unexpected status code {0} for URL {1}".format(response.status_code, handle))
	except Exception as e:
		print(e)
		return None

def dict_insert(dic, val, key, *keys):
	"""
	insert a value of a nested key into a dictionary

to insert value for a nested key, all ancestor keys should be given as
method's arguments

example:
  dict_insert({}, 'val', 'key1.key2'.split('.'))
	"""
	if len(keys) == 0:
		return dic[key] = val
	else:
		if not isinstance(dic, dict):
			raise TypeError('dict_insert() only works with dictionaries')
		if not isinstance(dic[key], dict):
			raise TypeError('dict_insert() can only insert values under '
							'dictionaries')
		for k in keys[:-1]:
			if not isinstance(dic[k], dict):
				dic[k] = {}
			elif not isinstance(dic[k], list):
				dic[k] = [dic[k]]
		dic[keys[-1]] = val
		return None

